# Iterate x from 1 to 3, y from x to 4, z from y to 5
solutions = []
for x in range(1, 4):
    for y in range(x, 5):
        for z in range(y, 6):
            if x**3 + y**3 + z**3 - x**2 * y**2 * z**2 == 0:
                solutions.append((x, y, z))

print(f"Found solutions in search range: {solutions}")

def check_equation(x, y, z):
    """Checks if x^3 + y^3 + z^3 = x^2*y^2*z^2 holds for positive integers."""
    lhs = x**3 + y**3 + z**3
    rhs = (x**2) * (y**2) * (z**2)
    return lhs == rhs

solutions = []
# Increased search bounds as requested
X_MAX = 3
Y_MAX = 15
Z_MAX = 500

print(f"Starting search with bounds: x <= {X_MAX}, y <= {Y_MAX}, z <= {Z_MAX}")

for x in range(1, X_MAX + 1):
    for y in range(x, Y_MAX + 1):
        for z in range(y, Z_MAX + 1):
            if check_equation(x, y, z):
                solutions.append((x, y, z))

print("--- Solutions Found ---")
if solutions:
    for sol in solutions:
        print(sol)
else:
    print("No solutions found in the specified range.")

def check_solution(x, y, z):
    """Checks if x^3 + y^3 + z^3 - x^2y^2z^2 = 0."""
    LHS = x**3 + y**3 + z**3
    RHS = x**2 * y**2 * z**2
    return LHS == RHS

